import pandas as pd
import numpy as np

# Load the test predictions and residuals generated by the ML pipeline
df = pd.read_csv("data/processed/test_residuals.csv")

print("Analytics dataset loaded successfully.")
print("Shape:", df.shape)

print("\nColumns:")
print(df.columns.tolist())

print("\nFirst 5 rows:")
print(df.head())

# Calculate absolute prediction error
df["absolute_error"] = np.abs(df["residual"])

print("\nAbsolute error calculated successfully.")
print(df[["y_true", "y_pred", "residual", "absolute_error"]].head())

# Identify over-predictions and under-predictions
df["over_predicted"] = df["residual"] < 0
df["under_predicted"] = df["residual"] > 0

print("\nPrediction direction:")
print(df[["y_true", "y_pred", "residual",
          "over_predicted", "under_predicted"]].head())

# Calculate prediction direction percentages
over_prediction_rate = df["over_predicted"].mean() * 100
under_prediction_rate = df["under_predicted"].mean() * 100

print("\nPrediction Direction KPIs:")
print(f"Over-prediction rate: {over_prediction_rate:.2f}%")
print(f"Under-prediction rate: {under_prediction_rate:.2f}%")

# Calculate overall regression error metrics
mae = df["absolute_error"].mean()
rmse = np.sqrt((df["residual"] ** 2).mean())
mean_residual = df["residual"].mean()

print("\nOverall Error KPIs:")
print(f"MAE: {mae:.4f}")
print(f"RMSE: {rmse:.4f}")
print(f"Mean residual: {mean_residual:.4f}")

# Analyze error distribution
min_residual = df["residual"].min()
max_residual = df["residual"].max()
median_absolute_error = df["absolute_error"].median()
residual_std = df["residual"].std()

print("\nError Distribution KPIs:")
print(f"Minimum residual: {min_residual:.4f}")
print(f"Maximum residual: {max_residual:.4f}")
print(f"Median absolute error: {median_absolute_error:.4f}")
print(f"Residual standard deviation: {residual_std:.4f}")

# Calculate Residual R-squared
ss_res = np.sum(df["residual"] ** 2)
ss_tot = np.sum((df["y_true"] - df["y_true"].mean()) ** 2)

residual_r2 = 1 - (ss_res / ss_tot)

print("\nResidual R-squared:")
print(f"Residual R²: {residual_r2:.4f}")

# Identify the largest prediction errors
top_errors = df.nlargest(10, "absolute_error")

print("\nTop 10 Largest Prediction Errors:")
print(top_errors[
    ["MedInc", "HouseAge", "AveRooms", "Population",
     "Latitude", "Longitude", "y_true", "y_pred",
     "residual", "absolute_error"]
].to_string(index=False))

# Analyze residuals by geographic location
geo_analysis = (
    df.groupby(["Latitude", "Longitude"])["residual"]
    .agg(["mean", "count"])
    .reset_index()
)

print("\nGeographic Residual Analysis:")
print(
    geo_analysis.sort_values("mean").head(10).to_string(index=False)
)

# Group observations into latitude bands
df["latitude_band"] = pd.cut(
    df["Latitude"],
    bins=5
)

geo_band_analysis = (
    df.groupby("latitude_band", observed=True)
    .agg(
        mean_residual=("residual", "mean"),
        mean_absolute_error=("absolute_error", "mean"),
        observations=("residual", "count")
    )
    .reset_index()
)

print("\nGeographic Error Analysis by Latitude Band:")
print(geo_band_analysis.to_string(index=False))